        从取号机获得一个号码;
        等待叫号;
        获得服务;
    }

    process 营业员
    {
        while (TRUE) {
            叫号;
            为顾客服务;
        }
    }
}coend
请添加必要的信号量和 P、V（或 wait() 、 signal() ）操作实现上述过程的互斥和同步。要求写出完整的过程，说明信号量的含义并赋初值。

